), inserted as (
  insert into public.venues (
    name,
    location_text,
    city,
    province,
    postal_code,
    country,
    website_url,
    venue_phone,
    latitude,
    longitude,
    indoor_outdoor,
    facility_type,
    booking_required,
    cost_type,
    supports_tennis,
    supports_pickleball,
    google_rating,
    working_hours,
    google_maps_url,
    google_place_id,
    season,
    has_lights,
    has_washroom,
    has_parking,
    accessibility,
    timezone,
    notes,
    venue_kind,
    access_type
  )
  select
    s.name,
    s.location_text,
    s.city,
    s.province,
    s.postal_code,
    s.country,
    s.website_url,
    s.venue_phone,
    s.latitude,
    s.longitude,
    s.indoor_outdoor,
    s.facility_type,
    s.booking_required::boolean,
    s.cost_type,
    s.supports_tennis,
    s.supports_pickleball,
    s.google_rating,
    s.working_hours,
    s.google_maps_url,
    s.google_place_id,
    s.season,
    s.has_lights::boolean,
    s.has_washroom::boolean,
    s.has_parking::boolean,
    s.accessibility,
    'America/Toronto',
    'Imported from venue candidate spreadsheet: Halton/Peel row.',
    s.venue_kind,
    s.access_type
  from seed_rows s
  where not exists (
    select 1
    from public.venues v
    where lower(btrim(v.name)) = lower(btrim(s.name))
      and lower(btrim(coalesce(v.city, ''))) = lower(btrim(coalesce(s.city, '')))
  )
  on conflict (google_place_id) where google_place_id is not null do nothing
  returning id, name, city
), inserted_seed as (
  select i.id, s.sport_codes, s.court_count
  from inserted i
  join seed_rows s
    on lower(btrim(i.name)) = lower(btrim(s.name))
   and lower(btrim(coalesce(i.city, ''))) = lower(btrim(coalesce(s.city, '')))
)
insert into public.venue_sports (venue_id, sport_id, court_count)
select distinct on (i.id, sp.id)
  i.id,
  sp.id,
  coalesce(i.court_count, 0)::integer
from inserted_seed i
cross join lateral unnest(i.sport_codes) as sport_code(code)
join public.sports sp on sp.code = sport_code.code
order by i.id, sp.id, i.court_count desc nulls last
on conflict (venue_id, sport_id) do update
set court_count = excluded.court_count;


