    ('William Rose Park', 'Oakville', 'William Rose Park', '455 Wheat Boom Dr., Oakville, ON L6H 0R4', 'Oakville', 'ON', 'L6H 0R4', 'Canada', 'https://www.oakville.ca/culturerec/parks-trails-gardens.html', '+1 905-845-6601', 43.49365, -79.71861, 'outdoor', 'court_only', null, null, true, false, 4.6, '{"Monday":["8a.m.-10p.m."],"Tuesday":["8a.m.-10p.m."],"Wednesday":["8a.m.-10p.m."],"Thursday":["8a.m.-10p.m."],"Friday":["8a.m.-10p.m."],"Saturday":["8a.m.-10p.m."],"Sunday":["8a.m.-10p.m."]}'::jsonb, 'https://www.google.com/maps/place/William+Rose+Park/@43.493649999999995,-79.71861,14z/data=!4m8!1m2!2m1!1sWilliam+Rose+Park!3m4!1s0x882b4372ff6cc905:0xf9dafbb7e83ee32!8m2!3d43.493649999999995!4d-79.71861', '0x882b4372ff6cc905:0xf9dafbb7e83ee32', 'summer_only', null, null, null, null, 'park', 'public', array['tennis']::text[], null)
), updated as (
  update public.venues v
  set
    name = u.name,
    location_text = coalesce(u.location_text, v.location_text),
    city = coalesce(u.city, v.city),
    province = coalesce(u.province, v.province),
    postal_code = coalesce(u.postal_code, v.postal_code),
    country = coalesce(u.country, v.country),
    website_url = coalesce(u.website_url, v.website_url),
    venue_phone = coalesce(u.venue_phone, v.venue_phone),
    latitude = coalesce(u.latitude, v.latitude),
    longitude = coalesce(u.longitude, v.longitude),
    indoor_outdoor = coalesce(u.indoor_outdoor, v.indoor_outdoor),
    facility_type = coalesce(u.facility_type, v.facility_type),
    booking_required = coalesce(u.booking_required::boolean, v.booking_required),
    cost_type = coalesce(u.cost_type, v.cost_type),
    supports_tennis = u.supports_tennis,
    supports_pickleball = u.supports_pickleball,
    google_rating = coalesce(u.google_rating, v.google_rating),
    working_hours = coalesce(u.working_hours, v.working_hours),
    google_maps_url = coalesce(u.google_maps_url, v.google_maps_url),
    google_place_id = coalesce(u.google_place_id, v.google_place_id),
    season = coalesce(u.season, v.season),
    has_lights = coalesce(u.has_lights::boolean, v.has_lights),
    has_washroom = coalesce(u.has_washroom::boolean, v.has_washroom),
    has_parking = coalesce(u.has_parking::boolean, v.has_parking),
    accessibility = coalesce(u.accessibility, v.accessibility),
    venue_kind = coalesce(u.venue_kind, v.venue_kind),
    access_type = coalesce(u.access_type, v.access_type)
  from update_rows u
  where lower(btrim(v.name)) = lower(btrim(u.match_name))
    and lower(btrim(coalesce(v.city, ''))) = lower(btrim(coalesce(u.match_city, '')))
  returning v.id, u.sport_codes, u.court_count
)
insert into public.venue_sports (venue_id, sport_id, court_count)
select distinct on (u.id, sp.id)
  u.id,
  sp.id,
  coalesce(u.court_count, 0)::integer
from updated u
cross join lateral unnest(u.sport_codes) as sport_code(code)
join public.sports sp on sp.code = sport_code.code
order by u.id, sp.id, u.court_count desc nulls last
on conflict (venue_id, sport_id) do update
set court_count = excluded.court_count;
